//! Persistent original diplomacy records. Only actual per-member JSON is
//! replaced during normal execution; complete JSON parsing is GEN/cold only.
use super::*;
use super::{original_rows::{OriginalProjectionRowsDataV1,OriginalProjectionRowDataV1},governance_rows::{Scalar,scalar}};
use oasis7_world_state::incremental_diplomacy::DiplomacyFieldV1 as Field;
use oasis7_world_state::{CrisisStatus,EconomicContractStatus,EconomicContractFulfillmentKind};
use oasis7_agent_api::world_action::ResourceKind;
use std::{sync::Arc,cell::RefCell,mem::size_of};
use serde::Serialize;
pub(super) struct OriginalDiplomacyRecordDataV1{field:Field,scalars:[Option<Arc<Scalar>>;18],members:Arc<OriginalProjectionRowsDataV1>,_fee:MemoryReservation}
fn reserve(common:&mut FormalBoundedContextV1<'_>,n:usize)->Result<MemoryReservation,BodyMutationError>{common.charge(1,n as u64).map_err(paid)?;common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory).map_err(Into::into)}
#[derive(Debug)]struct CodecCause{error:serde_json::Error,_fee:MemoryReservation}
impl std::fmt::Display for CodecCause{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.error.fmt(f)}}impl std::error::Error for CodecCause{}
fn fields(field:Field)->&'static[(&'static str,bool)]{match field{
Field::Alliances=>&[("alliance_id",false),("charter",false),("formed_by_agent_id",false),("formed_at",false)],
Field::Wars=>&[("war_id",false),("initiator_agent_id",false),("aggressor_alliance_id",false),("defender_alliance_id",false),("objective",false),("intensity",false),("active",false),("declared_mobilization_electricity_cost",false),("declared_mobilization_data_cost",false),("max_duration_ticks",false),("aggressor_score",false),("defender_score",false),("concluded_at",true),("winner_alliance_id",true),("loser_alliance_id",true),("settlement_summary",true),("declared_at",false)],
Field::Crises=>&[("crisis_id",false),("kind",false),("severity",false),("status",false),("opened_at",false),("expires_at",false),("resolver_agent_id",true),("strategy",true),("success",true),("impact",false),("resolved_at",true)],
Field::EconomicContracts=>&[("contract_id",false),("creator_agent_id",false),("counterparty_agent_id",false),("fulfillment_kind",false),("settlement_kind",false),("settlement_amount",false),("reputation_stake",false),("expires_at",false),("description",false),("status",false),("accepted_at",true),("settled_at",true),("settlement_success",true),("transfer_amount",false),("tax_amount",false),("settlement_notes",true)],
}}
fn position(field:Field,name:&str)->Result<usize,BodyMutationError>{fields(field).iter().position(|(actual,_)|*actual==name).ok_or_else(||invalid("diplomacy scalar field"))}
fn row<K:oasis7_world_state::incremental_semantic_key::SemanticKeyV1+?Sized,V:serde::Serialize+?Sized>(key:&K,value:&V,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<OriginalProjectionRowDataV1>,BodyMutationError>{let semantic=super::initial::capture(common,|out|oasis7_world_state::incremental_semantic_key::write_semantic_key_v1(key,out).map_err(paid))?;let key=super::capture_projection_json_data_v1(key,common)?;let value=super::capture_projection_json_data_v1(value,common)?;OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)}
impl OriginalDiplomacyRecordDataV1{
 pub(super) fn empty_for_new_actual_entity_v1(field:Field,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let members=Arc::new(OriginalProjectionRowsDataV1::empty_data_v1(common)?);Ok(Arc::new(Self{field,scalars:std::array::from_fn(|_|None),members,_fee:fee}))}
 pub(super) fn from_original_qualified_json_v1(field:Field,bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let phase=reserve(common,bytes.len().checked_mul(256).and_then(|n|n.checked_add(65536)).ok_or_else(||invalid("diplomacy cold JSON phase"))?)?;common.charge(bytes.len()as u64,bytes.len()as u64).map_err(paid)?;let decoded=serde_json::from_slice::<serde_json::Value>(bytes);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};let serde_json::Value::Object(mut values)=value else{return Err(invalid("diplomacy original object"))};let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut scalars=std::array::from_fn(|_|None);for(i,(name,optional))in fields(field).iter().enumerate(){common.consume_steps(1).map_err(paid)?;let value=match values.remove(*name){Some(v)=>v,None if *optional=>serde_json::Value::Null,_=>return Err(invalid("diplomacy original scalar missing"))};scalars[i]=Some(scalar(value,common)?)}let mut members=OriginalProjectionRowsDataV1::empty_data_v1(common)?;
 let collection=match field{Field::Alliances=>Some("members"),Field::Wars=>Some("participant_outcomes"),_=>None};if let Some(name)=collection{let serde_json::Value::Array(items)=values.remove(name).ok_or_else(||invalid("diplomacy original collection missing"))?else{return Err(invalid("diplomacy original collection type"))};for(index,value)in items.into_iter().enumerate(){common.consume_steps(1).map_err(paid)?;let index=u64::try_from(index).map_err(|_|invalid("diplomacy original ordinal"))?;let value=if field==Field::Alliances{let serde_json::Value::String(value)=value else{return Err(invalid("alliance original member type"))};row(&index,&value,common)?}else{let decoded=serde_json::from_value::<oasis7_world_state::WarParticipantOutcome>(value);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};row(&index,&value,common)?};members=members.with_row_data_v1(value,common)?}}
 if !values.is_empty(){return Err(invalid("diplomacy original extra fields"))}Ok(Arc::new(Self{field,scalars,members:Arc::new(members),_fee:fee}))}
 pub(super) fn validate(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{common.consume_steps(1).map_err(paid)?;if !self._fee.uses_budget(common.memory()){return Err(invalid("diplomacy resident pool"))}Ok(())}
 pub(super) fn scalar_is_optional_v1(&self,name:&str)->Result<bool,BodyMutationError>{let index=position(self.field,name)?;Ok(fields(self.field)[index].1)}
 fn get(&self,name:&str)->Result<&serde_json::Value,BodyMutationError>{self.scalars[position(self.field,name)?].as_ref().map(|v|v.value()).ok_or_else(||invalid("diplomacy scalar missing"))}
 fn text(&self,name:&str)->Result<&str,BodyMutationError>{self.get(name)?.as_str().ok_or_else(||invalid("diplomacy scalar string"))}fn uint(&self,name:&str)->Result<u64,BodyMutationError>{self.get(name)?.as_u64().ok_or_else(||invalid("diplomacy scalar unsigned"))}fn sint(&self,name:&str)->Result<i64,BodyMutationError>{self.get(name)?.as_i64().ok_or_else(||invalid("diplomacy scalar signed"))}fn boolean(&self,name:&str)->Result<bool,BodyMutationError>{self.get(name)?.as_bool().ok_or_else(||invalid("diplomacy scalar boolean"))}
 fn option_text(&self,name:&str)->Result<Option<&str>,BodyMutationError>{if self.get(name)?.is_null(){Ok(None)}else{self.text(name).map(Some)}}fn option_uint(&self,name:&str)->Result<Option<u64>,BodyMutationError>{if self.get(name)?.is_null(){Ok(None)}else{self.uint(name).map(Some)}}fn option_bool(&self,name:&str)->Result<Option<bool>,BodyMutationError>{if self.get(name)?.is_null(){Ok(None)}else{self.boolean(name).map(Some)}}
 pub(super) fn validate_complete_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{self.validate(common)?;common.consume_steps(18).map_err(paid)?;for(name,_)in fields(self.field){self.get(name)?;}Ok(())}
 fn fork(&self,common:&mut FormalBoundedContextV1<'_>)->Result<Self,BodyMutationError>{self.validate(common)?;let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;common.consume_steps(19).map_err(paid)?;Ok(Self{field:self.field,scalars:self.scalars.clone(),members:Arc::clone(&self.members),_fee:fee})}
 pub(super) fn with_scalar_v1(&self,name:&str,bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let index=position(self.field,name)?;let phase=reserve(common,bytes.len().checked_mul(128).and_then(|n|n.checked_add(32768)).ok_or_else(||invalid("diplomacy scalar phase"))?)?;common.charge(bytes.len()as u64,bytes.len()as u64).map_err(paid)?;let decoded=serde_json::from_slice(bytes);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};let value=scalar(value,common)?;let mut out=self.fork(common)?;out.scalars[index]=Some(value);Ok(Arc::new(out))}
 pub(super) fn with_member_v1(&self,semantic:ReservedValue<Vec<u8>>,key:ReservedValue<Vec<u8>>,after:Option<ReservedValue<Vec<u8>>>,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{if !matches!(self.field,Field::Alliances|Field::Wars){return Err(invalid("diplomacy member owner"))}let mut out=self.fork(common)?;let rows=match after{Some(value)=>self.members.with_row_data_v1(OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)?,common)?,None=>self.members.without_row_data_v1(&semantic,common)?};out.members=Arc::new(rows);Ok(Arc::new(out))}
 pub(super) fn members_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<&Arc<OriginalProjectionRowsDataV1>,BodyMutationError>{self.validate(common)?;Ok(&self.members)}
 pub(super) fn serialization_v1<'a,'b,'c>(&'a self,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>)->DiplomacySerialize<'a,'b,'c>{DiplomacySerialize{data:self,common,first}}
}
pub(super) struct DiplomacySerialize<'a,'b,'c>{data:&'a OriginalDiplomacyRecordDataV1,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>}
impl Serialize for DiplomacySerialize<'_,'_,'_>{fn serialize<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::Error as _;let result=self.data.validate(&mut self.common.borrow_mut()).and_then(|_|self.common.borrow_mut().charge(576,24768).map_err(paid));if let Err(error)=result{*self.first.borrow_mut()=Some(error);return Err(S::Error::custom("diplomacy source meter"))}let data=self.data;macro_rules! get{($e:expr)=>{match $e{Ok(v)=>v,Err(error)=>{*self.first.borrow_mut()=Some(error);return Err(S::Error::custom("diplomacy scalar source"))}}};}let members=data.members.original_value_sequence_serialization_v1(self.common,self.first);
 match data.field{
Field::Alliances=>oasis7_world_state::AllianceProjectionFieldsV1{alliance_id:get!(data.text("alliance_id")),members:&members,charter:get!(data.text("charter")),formed_by_agent_id:get!(data.text("formed_by_agent_id")),formed_at:get!(data.uint("formed_at")),}.serialize(serializer),
Field::Wars=>oasis7_world_state::WarProjectionFieldsV1{war_id:get!(data.text("war_id")),initiator_agent_id:get!(data.text("initiator_agent_id")),aggressor_alliance_id:get!(data.text("aggressor_alliance_id")),defender_alliance_id:get!(data.text("defender_alliance_id")),objective:get!(data.text("objective")),intensity:get!(u32::try_from(get!(data.uint("intensity"))).map_err(|_|invalid("diplomacy u32 source"))),active:get!(data.boolean("active")),declared_mobilization_electricity_cost:get!(data.sint("declared_mobilization_electricity_cost")),declared_mobilization_data_cost:get!(data.sint("declared_mobilization_data_cost")),max_duration_ticks:get!(data.uint("max_duration_ticks")),aggressor_score:get!(data.sint("aggressor_score")),defender_score:get!(data.sint("defender_score")),concluded_at:get!(data.option_uint("concluded_at")),winner_alliance_id:get!(data.option_text("winner_alliance_id")),loser_alliance_id:get!(data.option_text("loser_alliance_id")),settlement_summary:get!(data.option_text("settlement_summary")),participant_outcomes:&members,declared_at:get!(data.uint("declared_at")),}.serialize(serializer),
Field::Crises=>oasis7_world_state::CrisisProjectionFieldsV1{crisis_id:get!(data.text("crisis_id")),kind:get!(data.text("kind")),severity:get!(u32::try_from(get!(data.uint("severity"))).map_err(|_|invalid("diplomacy u32 source"))),status:match get!(data.text("status")){"active"=>CrisisStatus::Active,"resolved"=>CrisisStatus::Resolved,"timed_out"=>CrisisStatus::TimedOut,_=>{*self.first.borrow_mut()=Some(invalid("diplomacy enum source"));return Err(S::Error::custom("diplomacy enum source"))}},opened_at:get!(data.uint("opened_at")),expires_at:get!(data.uint("expires_at")),resolver_agent_id:get!(data.option_text("resolver_agent_id")),strategy:get!(data.option_text("strategy")),success:get!(data.option_bool("success")),impact:get!(data.sint("impact")),resolved_at:get!(data.option_uint("resolved_at")),}.serialize(serializer),
Field::EconomicContracts=>oasis7_world_state::EconomicContractProjectionFieldsV1{contract_id:get!(data.text("contract_id")),creator_agent_id:get!(data.text("creator_agent_id")),counterparty_agent_id:get!(data.text("counterparty_agent_id")),fulfillment_kind:match get!(data.text("fulfillment_kind")){"atomic_exchange"=>EconomicContractFulfillmentKind::AtomicExchange,"service"=>EconomicContractFulfillmentKind::Service,_=>{*self.first.borrow_mut()=Some(invalid("diplomacy enum source"));return Err(S::Error::custom("diplomacy enum source"))}},settlement_kind:match get!(data.text("settlement_kind")){"electricity"=>ResourceKind::Electricity,"data"=>ResourceKind::Data,_=>{*self.first.borrow_mut()=Some(invalid("diplomacy enum source"));return Err(S::Error::custom("diplomacy enum source"))}},settlement_amount:get!(data.sint("settlement_amount")),reputation_stake:get!(data.sint("reputation_stake")),expires_at:get!(data.uint("expires_at")),description:get!(data.text("description")),status:match get!(data.text("status")){"open"=>EconomicContractStatus::Open,"accepted"=>EconomicContractStatus::Accepted,"settled"=>EconomicContractStatus::Settled,"expired"=>EconomicContractStatus::Expired,_=>{*self.first.borrow_mut()=Some(invalid("diplomacy enum source"));return Err(S::Error::custom("diplomacy enum source"))}},accepted_at:get!(data.option_uint("accepted_at")),settled_at:get!(data.option_uint("settled_at")),settlement_success:get!(data.option_bool("settlement_success")),transfer_amount:get!(data.sint("transfer_amount")),tax_amount:get!(data.sint("tax_amount")),settlement_notes:get!(data.option_text("settlement_notes")),}.serialize(serializer),
}}}
